def check_schema_and_drop_if_needed():
    conn = get_connection()
    c = conn.cursor()
    try:
        c.execute("PRAGMA table_info(foods)")
        columns = [col['name'] for col in c.fetchall()]
        if len(columns) > 0 and 'typical_unit_weight_g' not in columns:
            print("Schema change detected: typical_unit_weight_g is missing. Re-seeding database.")
            c.execute("DROP TABLE IF EXISTS foods")
            c.execute("DROP TABLE IF EXISTS barcodes")
            c.execute("DROP TABLE IF EXISTS user_containers")
            c.execute("DROP TABLE IF EXISTS foods_fts")
    except Exception as e:
        print(f"Error checking schema: {e}")
    finally:
        conn.commit()
        conn.close()

def seed():
    check_schema_and_drop_if_needed()
    init_db()
    conn = get_connection()
    c = conn.cursor()

    c.execute("SELECT COUNT(*) FROM foods")
    if c.fetchone()[0] > 0:
        print("Database already seeded.")
        conn.close()
        return

    for item in SEED_DATA:
        c.execute('''
            INSERT INTO foods (slug, name_pt, name_en, category, cooking_method, density_g_cm3, kcal_100g, protein_100g, carbs_100g, fat_100g, fiber_100g, typical_unit_weight_g)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', item)

        c.execute('''
            INSERT INTO foods_fts (name_pt, name_en, category, slug)
            VALUES (?, ?, ?, ?)
        ''', (item[1], item[2], item[3], item[0]))

    conn.commit()
    print(f"Seeded {len(SEED_DATA)} food items.")
    conn.close()

if __name__ == "__main__":
    seed()
